INSERT INTO `v1_16363bc32942912671abf2fc43f26bc048897c7c190b3db2ef63e4b4b85e942d` VALUES (130911, 0, 0, 11, "アオイさんですよね～っ！？\nグランドリームパークへようこそっ♪\n本日はおひとりさまですますか？", 5146066, 1, 0, 66032, 1, 10);
